CREATE TABLE user (
    id              SERIAL PRIMARY KEY,
    prolific_pid    VARCHAR(100) UNIQUE,
    optout          BOOLEAN NOT NULL DEFAULT 0
);

CREATE TABLE image (
    id        SERIAL PRIMARY KEY,
    imgpath   VARCHAR(100) NOT NULL,
    question  VARCHAR(500) NOT NULL,
    dataset   VARCHAR(100) NOT NULL,
    category  VARCHAR(100) NOT NULL,
    locked    BIGINT UNSIGNED
);

CREATE TABLE triple (
    id                     SERIAL PRIMARY KEY,
    id_json                VARCHAR(100) NOT NULL,
    entity1                VARCHAR(100) NOT NULL,
    coords_entity1         VARCHAR(100) NOT NULL,
    relationship           VARCHAR(100) NOT NULL,
    entity2                VARCHAR(100) NOT NULL,
    coords_entity2         VARCHAR(100) NOT NULL,
    new_user_annotation    BOOLEAN NOT NULL DEFAULT 0,
    id_new_user_annotation VARCHAR(100),
    id_image               BIGINT UNSIGNED NOT NULL,
    FOREIGN KEY (id_image) REFERENCES image(id)
);

CREATE TABLE annotation (
    id                        SERIAL PRIMARY KEY,
    correctly_identified      BOOLEAN,
    new_label_entity1         VARCHAR(100),
    new_label_entity2         VARCHAR(100),
    new_coords_entity1        VARCHAR(100),
    new_coords_entity2        VARCHAR(100),
    entities_in_relationship  BOOLEAN,
    correct_relationship      BOOLEAN,
    new_relationship          VARCHAR(100),
    answer_question           BOOLEAN,
    id_triple                 BIGINT UNSIGNED NOT NULL,
    FOREIGN KEY (id_triple) REFERENCES triple(id),
    id_user                   BIGINT UNSIGNED NOT NULL,
    FOREIGN KEY (id_user) REFERENCES user(id)
);


